  await Promise.all([first, second]);
  assert.equal(streamStops, 1); assert.equal(serverCloses, 1); assert.deepEqual(s.fleetCalls, []);
  assert.equal((await request(s.web, { path: '/v1/auth/login', body: {} })).status, 503);
